// 5. Active Students
const studentWhereClause = isSchoolAdmin && userSchoolId
  ? { schoolId: userSchoolId, active: true }
  : { active: true };

const [currentStudents, previousStudents] = await Promise.all([
  prisma.student.count({ where: studentWhereClause }),
  prisma.student.count({
    where: {
      ...studentWhereClause,
      createdAt: { lt: monthStart },
    },
  }),
]);

const activeStudents = {
  value: currentStudents,
  change: calculateChange(currentStudents, previousStudents),
};

const statsCards = stats ? [
  // Solo mostrar para super_admin
  ...(user?.role === 'super_admin' ? [{
    label: 'Colegios Activos',
    value: stats.activeSchools.value.toString(),
    icon: School,
    change: stats.activeSchools.change,
    color: 'bg-blue-500',
  }] : []),
  // ... resto de cards
] : []

// 6. Total Wallet Balance
const walletAggregation = await prisma.wallet.aggregate({
  _sum: { balance: true },
  where: isSchoolAdmin && userSchoolId
    ? { student: { schoolId: userSchoolId } }
    : {},
});
const totalBalance = {
  value: walletAggregation._sum.balance || 0,
  formatted: formatCurrency(walletAggregation._sum.balance || 0),
};

// 7. Total Tickets
const ticketAggregation = await prisma.studentTicket.aggregate({
  _sum: { quantity: true },
  where: isSchoolAdmin && userSchoolId
    ? { student: { schoolId: userSchoolId } }
    : {},
});
const totalTickets = {
  value: ticketAggregation._sum.quantity || 0,
};
